  "claim": "A PodDisruptionBudget is written to policy/v1 with an empty spec.selector ({}).",
  "evidence": [
   {
    "quote": "an empty spec.selector ({}) written to a policy/v1 PodDisruptionBudget",
    "source": "Kubernetes Deprecated API Migration Guide",
    "release_of_change": "1.25"
   }
  ]
 }
]
